//! Generated files: a file the language's tools mark as generated code (a file-name pattern, or a
//! marker in the comments at the start of the file) is left as written when `skip_generated` is on.
//!
//! concept: generated-file-skip
//! what: Which files are generated code: file-name patterns and header markers, both plain option data.
//! tools: .NET formatters (generated-file names and `<auto-generated>` headers)
//! reads: option:skip_generated generated_names generated_header_markers generated_header_skip

use core_syntax::Grammar;

/// The data of the check: the options `generated_names` (globs on the file name without its last
/// extension, `*` only first or last: `*.g`, `Temp_*`), `generated_header_markers` (text searched
/// in the comments at the start of the file, case-insensitive; a `*` stands for any text within one line) and `generated_header_skip` (line
/// prefixes skipped while looking for those comments, like a preprocessor line).
pub struct GeneratedSpec<'a> {
    pub names: Vec<&'a str>,
    pub markers: Vec<&'a str>,
    pub skip: Vec<&'a str>,
}

/// Whether the file `id` (a path) with `text` is generated. Only the comments before the first
/// token are read.
pub fn is_generated(id: &str, text: &str, grammar: &Grammar, spec: &GeneratedSpec) -> bool {
    name_matches(id, &spec.names) || header_matches(text, grammar, spec)
}

fn name_matches(id: &str, globs: &[&str]) -> bool {
    let name = id.rsplit(['/', '\\']).next().unwrap_or(id);
    let stem = name
        .rsplit_once('.')
        .map_or(name, |(stem, _)| stem)
        .to_lowercase();
    globs.iter().any(|g| {
        let g = g.to_lowercase();
        match (g.strip_prefix('*'), g.strip_suffix('*')) {
            (Some(tail), _) => stem.ends_with(tail),
            (_, Some(head)) => stem.starts_with(head),
            _ => stem == g,
        }
    })
}

fn header_matches(text: &str, grammar: &Grammar, spec: &GeneratedSpec) -> bool {
    if spec.markers.is_empty() {
        return false;
    }
    let comments = &grammar.comments;
    let mut rest = text.trim_start();
    let mut head = String::new();
    loop {
        let line = comments.line.as_deref().filter(|p| rest.starts_with(*p));
        if let Some(prefix) = line {
            let end = rest.find('\n').unwrap_or(rest.len());
            head.push_str(&rest[prefix.len()..end]);
            head.push('\n');
            rest = rest[end..].trim_start();
        } else if let Some((open, close)) = comments
            .block
            .as_ref()
            .filter(|(o, _)| rest.starts_with(o.as_str()))
        {
            let end = rest[open.len()..]
                .find(close.as_str())
                .map_or(rest.len(), |i| open.len() + i);
            head.push_str(&rest[open.len()..end]);
            head.push('\n');
            rest = rest[(end + close.len()).min(rest.len())..].trim_start();
        } else if spec.skip.iter().any(|p| rest.starts_with(p)) {
            rest = rest[rest.find('\n').unwrap_or(rest.len())..].trim_start();
        } else {
            break;
        }
    }
    let head = head.to_lowercase();
    spec.markers.iter().any(|m| {
        let marker = m.to_lowercase();
        if !marker.contains('*') {
            return head.contains(&marker);
        }
        // `*` stands for any text within one line (`code generated *do not edit.`)
        head.lines().any(|line| {
            let mut rest = line;
            marker.split('*').all(|part| {
                rest.find(part).is_some_and(|at| {
                    rest = &rest[at + part.len()..];
                    true
                })
            })
        })
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn csharp() -> Grammar {
        Grammar::parse("language t 1\ntoken S\ncomments line \"//\" block \"/*\" \"*/\"\n").unwrap()
    }

    fn spec() -> GeneratedSpec<'static> {
        GeneratedSpec {
            names: vec!["TemporaryGeneratedFile_*", "*.g", "*.designer"],
            markers: vec!["<auto-generated", "<autogenerated"],
            skip: vec!["#"],
        }
    }

    #[test]
    fn name_pattern() {
        let g = csharp();
        assert!(is_generated("a/B.g.cs", "class A {}", &g, &spec()));
        assert!(is_generated("a/B.DESIGNER.cs", "class A {}", &g, &spec()));
        assert!(is_generated("TemporaryGeneratedFile_1.cs", "", &g, &spec()));
        assert!(!is_generated("a/Big.cs", "class A {}", &g, &spec()));
    }

    #[test]
    fn header_marker() {
        let g = csharp();
        let text = "#nullable disable\n// <auto-generated>\n// x\nclass A {}\n";
        assert!(is_generated("A.cs", text, &g, &spec()));
        assert!(is_generated(
            "A.cs",
            "/* <AutoGenerated /> */\nclass A {}",
            &g,
            &spec()
        ));
    }

    #[test]
    fn header_marker_with_a_wildcard() {
        let g = csharp();
        let spec = GeneratedSpec {
            names: Vec::new(),
            markers: vec!["code generated *do not edit."],
            skip: Vec::new(),
        };
        let line = "// Code generated by x. DO NOT EDIT.\npackage a\n";
        assert!(is_generated("a.go", line, &g, &spec));
        // the parts are in one line, in order
        assert!(!is_generated(
            "a.go",
            "// Code generated by x.\n// do not edit.\n",
            &g,
            &spec
        ));
        assert!(!is_generated(
            "a.go",
            "// do not edit. Code generated\n",
            &g,
            &spec
        ));
    }

    #[test]
    fn header_not_at_start() {
        let g = csharp();
        assert!(!is_generated(
            "A.cs",
            "class A {}\n// <auto-generated>\n",
            &g,
            &spec()
        ));
        assert!(!is_generated(
            "A.cs",
            "using System;\n// <auto-generated>\n",
            &g,
            &spec()
        ));
    }
}
